from collections import deque

def admit(requests, capacity, refill_every, window, window_max):
    results = []
    client_tokens = {}
    client_last_time = {}
    admitted_times = deque()

    for t, client, cost in requests:
        if client not in client_tokens:
            client_tokens[client] = capacity
            client_last_time[client] = 0

        last_time = client_last_time[client]
        if t > last_time:
            # count multiples of refill_every in (last_time, t]
            if refill_every > 0:
                count = (t // refill_every) - (last_time // refill_every)
            else:
                count = 0
            if count > 0:
                client_tokens[client] = min(capacity, client_tokens[client] + count)
            client_last_time[client] = t

        # purge window
        while admitted_times and admitted_times[0] <= t - window:
            admitted_times.popleft()

        if client_tokens[client] >= cost and len(admitted_times) < window_max:
            client_tokens[client] -= cost
            admitted_times.append(t)
            results.append(True)
        else:
            results.append(False)

    return results

